import React,{useState,useEffect,useRef} from 'https://esm.sh/react@18.2.0';
import ReactDOM from 'https://esm.sh/react-dom@18.2.0';

const waiters=new Map();
function accept(model){const r=model.response;if(r?.request_id&&waiters.has(r.request_id)){const w=waiters.get(r.request_id);waiters.delete(r.request_id);clearTimeout(w.timer);w.resolve(r);}}
async function rpc(payload){const id=crypto.randomUUID();return new Promise(async(resolve,reject)=>{const timer=setTimeout(()=>{waiters.delete(id);reject(new Error('La réponse tarde. Actualisez pour vérifier le résultat avant de réessayer.'));},25000);waiters.set(id,{resolve,reject,timer});try{await appsmith.updateModel({request:{...payload,request_id:id}});await appsmith.triggerEvent('onResetClick');accept(appsmith.model);}catch(e){clearTimeout(timer);waiters.delete(id);reject(new Error('Connexion indisponible. Réessayez dans un instant.'));}});}
const paths={home:'M3 10l9-7 9 7M5 9v12h14V9M9 21v-8h6v8',search:'M21 21l-6-6M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',plus:'M12 5v14M5 12h14',history:'M3 11a9 9 0 1 1 2 7M3 4v7h7M12 7v6l4 2',profile:'M20 21v-2a8 8 0 0 0-16 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',message:'M21 11a9 9 0 0 1-9 9H4l-3 3V11a10 10 0 0 1 20 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',car:'M3 12l2-7h14l2 7M3 12h18v7H3zM6 19v3M18 19v3M6 15h2M16 15h2',arrow:'M15 5l-7 7 7 7',pin:'M20 9c0 6-8 13-8 13S4 15 4 9a8 8 0 1 1 16 0M15 9a3 3 0 1 1-6 0 3 3 0 0 1 6 0',check:'M4 12l5 5L20 6',logout:'M9 3H3v18h6M12 12h10M17 7l5 5-5 5',star:'M12 2l3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1z',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12M15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',send:'M22 2L9 15M22 2l-7 20-6-7-7-6 20-7',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2'};
function Icon({name,size=20}){return <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name]||paths.car}/></svg>}
const money=n=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(Number(n||0));
const day=s=>new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'numeric',month:'short',year:'numeric',timeZone:'Europe/Paris'}).format(new Date(s));
const hour=s=>s?new Intl.DateTimeFormat('fr-FR',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Paris'}).format(new Date(s)):'';
const initials=n=>(n||'?').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase();
const norm=s=>(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function Field({label,id,error,children,help}){return <div className="field"><label htmlFor={id}>{label}</label>{children}{help&&<small id={id+'-help'}>{help}</small>}{error&&<small className="err" id={id+'-error'}>{error}</small>}</div>}
