function App(){
 const [page,setPage]=useState('welcome'),[data,setData]=useState(null),[token,setToken]=useState(''),[busy,setBusy]=useState(false),[error,setError]=useState(''),[notice,setNotice]=useState(''),[modal,setModal]=useState(null),[tripId,setTripId]=useState(null),[dashTab,setDashTab]=useState('all'),[search,setSearch]=useState({from:'',to:'',date:''}),[filters,setFilters]=useState({price:'',before:'',seats:'1'}),[chatWith,setChatWith]=useState(null),[msg,setMsg]=useState(''),[rating,setRating]=useState(5),[auth,setAuth]=useState({name:'',password:'',confirm:'',school:'',starting_point:''}),[form,setForm]=useState({starting_point:'',end_point:'',date:'',time:'',arrival:'',seats_total:'3',price:'3',meeting_point:'',stops:[]}),[edit,setEdit]=useState(null);
