 function view(t,manage=false){setTripId(t.id);go(manage?'manage':'detail');}
 function contact(t,id){setChatWith({id:id||t.author_id,name:id?bookings.find(b=>b.passenger_id===id)?.passenger_name:t.driver_name,trip:t.id});go('chat');act('read_messages',{sender_id:id||t.author_id});}
 const empty=(title,text,button,fn,icon='car')=><div className="empty"><span className="empty-icon"><Icon name={icon} size={32}/></span><h2>{title}</h2><p>{text}</p>{button&&<button className="btn" onClick={fn}>{button}</button>}</div>;
 const status=t=>t.status==='cancelled'?'Annulé':t.departure_at<new Date().toISOString()?'Terminé':t.seats_available<=0?'Complet':'Publié';
 function card(t,mode='normal'){const b=myBooking(t);return <article className="tripcard" key={t.id}><div className="row muted tiny"><span><Icon name={own(t)?'car':'profile'} size={15}/> {own(t)?'Conducteur':'Passager · avec '+t.driver_name}</span><span className={'badge '+(t.status==='cancelled'?'danger':'')}>• {b?'Confirmée':status(t)}</span></div><div className="route"><p><i/>{t.starting_point}</p><p><i/>{t.end_point}</p></div><p className="tiny muted">▦ {day(t.departure_at)} · {hour(t.departure_at)}{t.arrival_at?' → '+hour(t.arrival_at):''}</p><div className="row tiny"><span className="muted">{t.seats_available} place{t.seats_available>1?'s':''} disponible{t.seats_available>1?'s':''}</span><strong>{money(t.price)} / place</strong></div><div className="row buttons"><button className="btn secondary" onClick={()=>view(t)}>Voir le trajet</button>{own(t)&&mode!=='result'&&<button className="btn secondary" onClick={()=>view(t,true)}>Gérer</button>}{b&&mode!=='result'&&<button className="btn secondary" onClick={()=>contact(t)}>Contacter</button>}</div></article>}
 const coming=trips.filter(t=>t.status==='published'&&new Date(t.departure_at)>new Date()&&(own(t)||myBooking(t))).sort((a,b)=>a.departure_at.localeCompare(b.departure_at));
