 const results=trips.filter(t=>t.status==='published'&&new Date(t.departure_at)>new Date()&&!own(t)&&norm(t.starting_point).includes(norm(search.from))&&norm(t.end_point).includes(norm(search.to))&&(!search.date||new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Paris',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(t.departure_at))===search.date)&&t.seats_available>=Number(filters.seats)&&(!filters.price||Number(t.price)<=Number(filters.price))&&(!filters.before||hour(t.departure_at)<=filters.before)).sort((a,b)=>a.departure_at.localeCompare(b.departure_at));
 const headings={dashboard:'',search:'Rechercher un trajet',results:'Trajets disponibles',publish:'Publier un trajet',published:'Mes trajets publiés',detail:'Détails du trajet',manage:'Gestion du trajet',history:'Historique',profile:'Profil',edit:'Modifier mes informations',reviews:'Avis reçus',settings:'Paramètres',messages:'Messages',chat:'Messages',notifications:'Notifications',review:'Laisser un avis'};
