 return <div className="app"><div className="phone"><header className="top"><div className="brand"><span className="logo"><Icon name="car" size={20}/></span>Campus<span>Ride</span></div>{profile&&<div className="header-actions"><button className="iconbtn" aria-label="Notifications" onClick={()=>go('notifications')}><Icon name="bell"/>{notifications.some(n=>!n.read_at)&&<i className="unread"/>}</button><button className="avatar" aria-label="Mon profil" onClick={()=>go('profile')}>{profile.avatar_url?<img alt="Votre profil" src={profile.avatar_url}/>:initials(profile.name)}</button></div>}</header>
