ose();});return;}act(modal.kind==='reserve'?'reserve':modal.kind,{trip_id:trip.id,booking_id:modal.booking?.id},()=>{setNotice(modal.kind==='reserve'?'Réservation confirmée.':'Annulation enregistrée.');close();});}}>{modal.kind==='reserve'?'Confirmer la réservation':modal.kind==='logout'?'Se déconnecter':modal.kind==='leave'?'Quitter le formulaire':'Oui, annuler'}</button></section></div>}
